                    # Check if we have any non-numeric keys
                    has_non_numeric = any(not k.isdigit() for k in current.keys())
                    if has_non_numeric:
                        raise ValueError(f"Conflict: key '{key}' would create list but parent has dict keys")

                    # Convert dict to list if needed
                    if len(current) == 0:
                        current = []
                    else:
                        # Convert existing numeric-key dict to list
                        dict_items = []
                        for k, v in current.items():
                            if k.isdigit():
                                dict_items.append((int(k), v))
                            else:
                                raise ValueError(f"Cannot convert dict with non-numeric keys to list")

                        if len(dict_items) == 0:
                            current = []
                        else:
                            indices = sorted([idx for idx, _ in dict_items])
                            if indices != list(range(len(indices))):
                                raise ValueError(f"List indices are not dense: {indices}")

                            # Create list with values in order
                            current = [v for _, v in sorted(dict_items)]

                # Now current is definitely a list
                # Extend list if needed
                while len(current) <= index:
                    current.append(None)

                if is_last:
                    # Set the leaf value
                    current[index] = value
                else:
                    # Navigate deeper
                    next_part = parts[i + 1]
                    if current[index] is None:
                        if next_part.isdigit():
                            current[index] = []
                        else:
                            current[index] = {}
                    current = current[index]
            else:
                # This is a dict key
                if isinstance(current, list):
                    raise ValueError(f"Conflict: expected dict but got list at index {i} for key '{key}'")

                if not isinstance(current, dict):
                    raise ValueError(f"Expected dict at index {i} for key '{key}'")

                if is_last:
                    current[part] = value
                else:
                    if part not in current:
                        next_part = parts[i + 1]
                        if next_part.isdigit():
                            current[part] = []
                        else:
                            current[part] = {}
                    current = current[part]

    # Final validation: check for dense list indices
    # We need to traverse the result and validate all lists have dense indices

    def validate_structure(obj, path=""):
        if isinstance(obj, dict):
            for k, v in obj.items():
                validate_structure(v, f"{path}.{k}" if path else k)
        elif isinstance(obj, list):
            # Check if indices are dense 0..n-1
            for i, item in enumerate(obj):
                # Check if index i exists in the list
                if i >= len(obj):
                    raise ValueError(f"List indices are not dense at {path}")
            # Check if all indices from 0 to len-1 exist
            if len(obj) > 0:
                for i in range(len(obj)):
                    if i >= len(obj):
                        raise ValueError(f"List indices are not dense at {path}")

    validate_structure(result)

